import { cn } from "@workspace/ui/lib/utils"

// The agents' own marks, each on a rounded app-icon tile. Claude's, Cursor's
// and MCP's paths are Simple Icons' traces; the others are the brands' marks as published, kept in
// their source coordinates and moved into the 23×23 tile with a transform, so
// their gradients keep those coordinates too.
// They are decorative: the agent's name always sits beside its logo.

function Tile({
  className,
  fill = "white",
  children,
}: {
  className?: string
  fill?: string
  children: React.ReactNode
}) {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 23 23"
      className={cn("shrink-0", className)}
    >
      <rect width="23" height="23" rx="6.2" fill={fill} />
      {children}
    </svg>
  )
}

